<?php if(in_array($service,['telegram','discord','signal'],true)){include __DIR__.'/integration_community.php';return;}?>
    <?php if($service==='facebook_pages'):?><details class="pub-card"><summary>Optional Facebook Page integration</summary><p>Your personal professional-mode profile does not need Page discovery. Saved app credentials remain available for separately managed Pages.</p><?php endif;?>
    <article class="pub-card pub-provider" id="<?=e($service)?>"><div class="pub-card-top"><h3><?=e($definition['name'])?></h3><span class="pub-status <?=e($status)?>"><?=e(publishing_state_label($status))?></span></div>
      <p><?=e($definition['description'])?></p>
      <?php if($service==='facebook_profile'):?><p class="pub-help">Use an app configured for standard Facebook Login. Business Login/Page credentials are separate and are not reused here. Connecting confirms identity only; prepare and finish personal-profile posts in Facebook.</p><?php endif;?>
      <?php if($connection&&$connection['external_id']):?><dl><dt>Provider account</dt><dd><?=e($connection['display_name'])?></dd><dt>Account ID</dt><dd><?=e($connection['external_id'])?></dd><dt>Last verified</dt><dd><?=e(publishing_local_time($connection['verified_at']))?></dd><?php if($connection['selected_resource']):?><dt>Destination</dt><dd><?php $selectedName=$connection['selected_resource'];foreach($resources as $resource)if($resource['id']===$connection['selected_resource'])$selectedName=$resource['name'];?><?=e($selectedName)?></dd><?php endif;?></dl><?php endif;?>
      <?php if($service==='tiktok_business'&&!empty($metadata['accounts_api'])):$nativeSettings=is_array($metadata['settings']??null)?$metadata['settings']:[];?>
        <details class="pub-small-gap"><summary>Observed TikTok account settings</summary><p class="pub-help">Returned by the Accounts API at verification. Delivery checks the current settings again.</p><dl>
          <?php foreach(['is_business_account'=>'Business account flag','has_advanced_access'=>'Advanced access'] as $key=>$label):?><dt><?=e($label)?></dt><dd><?=is_bool($metadata[$key]??null)?($metadata[$key]?'Yes':'No'):'Not returned'?></dd><?php endforeach;?>
          <dt>Video duration limit</dt><dd><?=is_numeric($nativeSettings['max_video_post_duration_sec']??null)?e((string)min(600,(float)$nativeSettings['max_video_post_duration_sec'])).' seconds':'Not returned'?></dd>
          <?php foreach(['comment_disabled'=>'Comments','duet_disabled'=>'Duet','stitch_disabled'=>'Stitch'] as $key=>$label):?><dt><?=e($label)?></dt><dd><?=is_bool($nativeSettings[$key]??null)?($nativeSettings[$key]?'Restricted':'Allowed'):'Not returned'?></dd><?php endforeach;?>
        </dl></details>
      <?php endif;?>
      <?php if($status==='pending_confirmation'):?>
        <?php if($resources):?><form method="post" action="<?=url('/write/connections/'.$service.'/confirm')?>"><?=csrf_field()?><div class="field"><label for="resource-<?=e($service)?>">Returned destination</label><select required name="resource" id="resource-<?=e($service)?>"><?php foreach($resources as $resource):?><option value="<?=e((string)$resource['id'])?>"><?=e($resource['name'].' · '.$resource['id'])?></option><?php endforeach;?></select></div><label class="pub-choice"><input type="checkbox" name="confirm_identity" required><span>This is the account and destination I want to use.</span></label><button class="wbtn primary" type="submit">Confirm destination</button></form>
        <?php else:?><div class="pub-hint pub-warning">The provider returned an identity but no eligible resource for this feature. Check the account’s site/property/Page/channel access, then reconnect.</div><?php endif;?>
      <?php endif;?>
      <?php if($service==='buffer'):?><form method="post" action="<?=url('/write/connections/buffer/connect')?>"><?=csrf_field()?><div class="field"><label for="buffer-key">Buffer API key</label><input id="buffer-key" type="password" name="api_key" autocomplete="new-password" required placeholder="Paste a key from your own Buffer account"><span class="pub-input-note">The key is encrypted. The next step reads your account and channels; it does not create a post.</span></div><button class="wbtn" type="submit"><?=$status==='connected'?'Reconnect Buffer':'Connect Buffer'?></button></form>
      <?php else:$client=publishing_service_client($service);$configured=$client['client_id']!==''&&$client['client_secret']!=='';?>
        <?php if($configured):?><form method="post" action="<?=url('/write/connections/'.$service.'/start')?>"><?=csrf_field()?><button type="submit" class="wbtn primary"><?=$status==='disconnected'?'Connect':'Reconnect'?></button></form><?php endif;?>
        <?php $namespace=publishing_client_namespace($service);?><details class="integration-setup" id="setup-<?=e($service)?>"><summary class="<?=$configured?'pub-help':'wbtn primary'?>"><?=$configured?'App setup & callback':'Connect'?></summary>
        <p class="pub-help"><?=$configured?'Update this service’s app credentials only if needed.':'Set up this service here, then continue to its secure account authorisation.'?> Blank fields retain saved values. Never enter your account password.</p>
        <form method="post" action="<?=url('/write/connections/settings')?>"><?=csrf_field()?><input type="hidden" name="setup_service" value="<?=e($service)?>"><label for="client-<?=e($service)?>">Client / app ID <?=$client['client_id']!==''?'· saved':''?></label><input id="client-<?=e($service)?>" type="password" name="<?=e($namespace)?>_client_id" autocomplete="new-password" <?=$client['client_id']===''?'required':''?> placeholder="Enter this app’s client ID">
        <label for="secret-<?=e($service)?>">Client / app secret <?=$client['client_secret']!==''?'· saved':''?></label><input id="secret-<?=e($service)?>" type="password" name="<?=e($namespace)?>_client_secret" autocomplete="new-password" <?=$client['client_secret']===''?'required':''?> placeholder="Leave blank to retain a saved secret">
        <p class="pub-help">Authorised redirect URI</p><div class="pub-code"><?=e(publishing_callback_url($service))?></div>
        <?php if(in_array($namespace,['instagram','facebook','facebook_profile'],true)):?><label>Meta Graph API version<input name="meta_version" value="<?=e(publishing_meta_version())?>" pattern="v[0-9]{2}\\.0"></label><?php endif;?>
        <?php if($service==='tiktok_business'):?><label>Account-holder authorisation URL<input type="url" name="tiktok_business_authorization_url" autocomplete="off" placeholder="URL from your approved Accounts API app"></label><?php endif;?>
        <div class="integration-actions"><button class="wbtn primary" name="save_and_connect" value="1">Save & connect</button><button class="wbtn" name="save_and_connect" value="0">Save setup</button></div></form></details>
        <details class="pub-small-gap"><summary class="pub-help">Requested permissions</summary><div class="pub-code"><?=e(implode("\n",$definition['scopes']))?></div></details>
      <?php endif;?>
      <?php if($status==='connected'&&in_array($service,['google_search_console','google_analytics','google_youtube_read','google_youtube_upload','tiktok_read'],true)):?><form method="post" action="<?=url('/write/connections/'.$service.'/report')?>"><?=csrf_field()?><button class="wbtn" type="submit">Read current report</button></form><?php endif;?>
      <?php if($status==='connected'&&in_array($service,['instagram_comments','instagram_messages'],true)):?><a class="wbtn" href="<?=url('/write/connections/'.$service.'/engagement')?>">Open engagement desk</a><?php endif;?>
      <?php if($connection&&$status!=='disconnected'):?><form method="post" action="<?=url('/write/connections/'.$service.'/disconnect')?>"><?=csrf_field()?><button class="pub-muted-button" type="submit">Remove saved connection</button></form><?php endif;?>
    </article><?php if($service==='facebook_pages'):?></details><?php endif;?>
